package com.aoo.bcg.gifting;
import javax.sql.DataSource;import java.sql.*;import java.time.*;import java.util.Objects;
/** Fail-closed anti-abuse decision using durable risk events and gift device/IP velocity. */
public final class JdbcRiskAuthority implements GiftingPorts.RiskAuthority {private final DataSource source;private final Clock clock;public JdbcRiskAuthority(DataSource s,Clock c){source=Objects.requireNonNull(s);clock=c;}public GiftingPorts.Decision evaluate(long sender,long recipient,String asset,long quantity,String device,String ip)throws Exception{try(Connection c=source.getConnection()){int score=0;try(PreparedStatement q=c.prepareStatement("SELECT COALESCE(MAX(risk_score),0) FROM risk_event WHERE player_id IN (?,?) AND status IN ('PENDING_REVIEW','CONFIRMED') AND created_at>=?")){q.setLong(1,sender);q.setLong(2,recipient);q.setTimestamp(3,Timestamp.from(clock.instant().minus(Duration.ofHours(24))));try(ResultSet r=q.executeQuery()){r.next();score=r.getInt(1);}}try(PreparedStatement q=c.prepareStatement("SELECT COUNT(DISTINCT sender_id) FROM gift_transfer WHERE (device_id=? OR ip_address=?) AND created_at>=?")){q.setString(1,device);q.setString(2,ip);q.setTimestamp(3,Timestamp.from(clock.instant().minus(Duration.ofHours(1))));try(ResultSet r=q.executeQuery()){r.next();if(r.getInt(1)>=3)score=Math.max(score,85);}}return new GiftingPorts.Decision(score<80,score<80?"ALLOW":"HIGH_RISK",score);}}}
